{
    "predictors": [
        {
            "name": "Patent Count Growth",
            "construction": "Annual growth rate of the number of patents filed by the firm, sourced from the US Patent Office data.",
            "rationale": "Firms with increasing patent filings may be innovating more and potentially gaining competitive advantages.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Employee Growth Rate",
            "construction": "Annual percentage change in the number of employees, sourced from firm 10-K filings.",
            "rationale": "Growing firms might be expanding operations, indicating future earnings growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "CEO Tenure",
            "construction": "Number of years the current CEO has been in position, sourced from company reports.",
            "rationale": "Longer-tenured CEOs might have more experience and stability, potentially leading to better firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Board Independence Ratio",
            "construction": "Ratio of independent directors to total directors on the board, sourced from proxy statements.",
            "rationale": "Higher board independence might improve governance and firm decision-making.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Marketing Spend Ratio",
            "construction": "Ratio of marketing expenditures to total sales, sourced from the firm's income statement.",
            "rationale": "Higher marketing expenditures might lead to increased brand recognition and sales growth.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Supplier Concentration",
            "construction": "Percentage of total purchases from the top three suppliers, sourced from 10-K filings.",
            "rationale": "Lower supplier concentration may reduce risk of supply chain disruptions.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Insider Trading Activity",
            "construction": "Net number of shares bought by insiders over the past year, sourced from SEC Form 4 filings.",
            "rationale": "Insider buying may signal confidence in future firm performance.",
            "higher_returns_for": "high values of the measure"
        },
        {
            "name": "Environmental Compliance Ratio",
            "construction": "Total environmental fines as a percentage of total revenue, sourced from EPA disclosures.",
            "rationale": "Firms with fewer environmental fines may face fewer regulatory risks and costs.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Product Recall Frequency",
            "construction": "Number of times products were recalled in the previous year, sourced from company announcements.",
            "rationale": "Frequent product recalls may indicate quality issues and reputational damage.",
            "higher_returns_for": "low values of the measure"
        },
        {
            "name": "Cash Conversion Efficiency",
            "construction": "Operating cash flow divided by net sales, sourced from the firm's cash flow statement.",
            "rationale": "Better cash conversion indicates efficient operations and potential liquidity benefits.",
            "higher_returns_for": "high values of the measure"
        }
    ]
}
